export const body = "<h2>Unreal Engine 5 Findings from the artist</h2>\n\n<p>Jump To Video</p>\n\n<p><span class=\"source-divider\" role=\"separator\"></span></p>\n\n<ul><li>Quick links to understand interesting features in UE5 in 3 minutes</li><li>Detailed information about Lumen, Nanite, Virtual Shadow Maps, and World Partition</li></ul>\n\n<ul><li>Lumen</li><li>Nanite</li><li>Virtual shadow maps</li><li>World partition</li></ul>\n\n<ul><li>Recording</li></ul>\n\n<p>After a year of radio silence, Unreal Engine 5 recently resurfaced with a 15-minute video. The short presentation expounded on Lumen and Nanite and then introduced a variety of new features. More importantly, the showcase ended with an announcement for Early Access, which got more than a few people very excited.</p>\n\n<p>In response to the exciting news, our Software Engineering (SE) team tinkered with the engine, and they had a long list of interesting findings to share.</p>\n\n<p>They were joined by the artist, a senior Lighting Artist with UE experience. Before the meet-up, the artist experimented with Lumen and captured some pictures to illustrate the lighting prowess of this system.</p>\n\n<p>And that is the backstory of this summary. Now we get to the summary.</p>\n\n<h3>Quick links to understand interesting features in UE5 in 3 minutes</h3>\n\n<ul><li><strong>Lumen</strong></li></ul>\n\n<p>Better quality and more efficient lighting | details here.</p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/76608a74949b904a969a.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/76608a74949b904a969a.webp\" width=\"1150\" height=\"647\" style=\"--source-width:566px\" alt=\"Illustration 1\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<ul><li><strong>Nanite</strong></li></ul>\n\n<p>Goodbye LODs, hello Photogrammetry and Zbrush models | details here.</p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/6e25b6c337cedd1e14f4.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/6e25b6c337cedd1e14f4.webp\" width=\"1150\" height=\"313\" style=\"--source-width:566px\" alt=\"Illustration 2\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<ul><li><strong>Virtual shadow maps</strong></li></ul>\n\n<p>All-in-one shadow map with better performance | details here.</p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/9efd450f9fe4ae7c547d.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/9efd450f9fe4ae7c547d.webp\" width=\"723\" height=\"281\" style=\"--source-width:566px\" alt=\"Illustration 3\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<ul><li><strong>World partition</strong></li></ul>\n\n<p>Flexible level streaming and management | details here.</p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/10b0284cb6c2f62a4fb3.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/10b0284cb6c2f62a4fb3.webp\" width=\"1043\" height=\"711\" style=\"--source-width:367px\" alt=\"Illustration 4\" loading=\"lazy\" decoding=\"async\"></a><a class=\"source-figure\" href=\"assets/library-inline/588fd1faca4137052bcd.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/588fd1faca4137052bcd.webp\" width=\"1150\" height=\"804\" style=\"--source-width:357px\" alt=\"Illustration 5\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<ul><li><strong>One file per Actor</strong></li></ul>\n\n<p>Allows multiple people to work on the same location in a level simultaneously | for details go to video at 22:45.</p>\n\n<ul><li><strong>Level instance</strong></li></ul>\n\n<p>Generalization of Prefabs | for details go to video at 24:00.</p>\n\n<ul><li><strong>Full body IK solver</strong></li></ul>\n\n<p>Easily creates natural animation | for details go to video at 26:18.</p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/79dc352c7c752c693e6e.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/79dc352c7c752c693e6e.webp\" width=\"900\" height=\"450\" style=\"--source-width:566px\" alt=\"Illustration 6\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<ul><li><strong>Motion warping</strong></li></ul>\n\n<p>Adapts root animation to the environment | for details go to video at 26:18.</p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/e0b406c8db5443723576.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/e0b406c8db5443723576.webp\" width=\"900\" height=\"500\" style=\"--source-width:566px\" alt=\"Illustration 7\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<ul><li><strong>Control rig</strong></li></ul>\n\n<p>Quickly creates rigs and shares them across multiple characters | for details go to video at 26:18.</p>\n\n<ul><li><strong>New hair rendering</strong></li></ul>\n\n<p>Better strand simulation.</p>\n\n<ul><li><strong>MetaSounds</strong></li></ul>\n\n<p>Full audio pipeline inside Unreal Engine | for details go to video at 27:30.</p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/7a164c3072ae991f1bbf.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/7a164c3072ae991f1bbf.webp\" width=\"1150\" height=\"649\" style=\"--source-width:566px\" alt=\"Illustration 8\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<ul><li><strong>Data registries</strong></li></ul>\n\n<p>Allows running a unified database inside the engine | for details go to video at 28:46.</p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/97c4954b6900f9ee08bf.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/97c4954b6900f9ee08bf.webp\" width=\"1022\" height=\"365\" style=\"--source-width:566px\" alt=\"Illustration 9\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<ul><li><strong>New Temporal AA &amp; Temporal Super Resolution</strong></li></ul>\n\n<p>Sharper edges and better resolution upscaling | for details go to video at 29:20.</p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/413ea56cf67b466ea74c.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/413ea56cf67b466ea74c.webp\" width=\"1150\" height=\"647\" style=\"--source-width:566px\" alt=\"Illustration 10\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/0077a445037946b2c768.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/0077a445037946b2c768.webp\" width=\"1150\" height=\"647\" style=\"--source-width:566px\" alt=\"Illustration 11\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<ul><li><strong>Feature plugins</strong></li></ul>\n\n<p>Allows creating new plugins that are transferable | for details go to video at 30:14.</p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/151e1041c2c5a2a6bdad.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/151e1041c2c5a2a6bdad.webp\" width=\"961\" height=\"322\" style=\"--source-width:566px\" alt=\"Illustration 12\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<ul><li><strong>Asset virtualization (in development)</strong></li></ul>\n\n<p>Allows artists to work only on a subset of a project | for details go to video at 30:45.</p>\n\n<ul><li><strong>Unreal Turnkey</strong></li></ul>\n\n<p>Automatically installs existing tools and data when starting a new project | for details go to video at 31:17.</p>\n\n<ul><li><strong>New Input System</strong></li></ul>\n\n<p>Modular support for different input devices | for details go to video at 32:00.</p>\n\n<ul><li><strong>New Unreal Insights</strong></li></ul>\n\n<p>Main tool for measuring performance and profiling hot-spots | for details go to video at 32:24.</p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/a85b47574aae3fc17b72.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/a85b47574aae3fc17b72.webp\" width=\"1150\" height=\"671\" style=\"--source-width:566px\" alt=\"Illustration 13\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n\n\n<h3><span class=\"source-divider\" role=\"separator\"></span>Detailed information about Lumen, Nanite, Virtual Shadow Maps, and World Partition</h3>\n\n<h4>Lumen</h4>\n\n<p>Lumen</p>\n\n<p>Lumen is a software-based raytracing system that provides dynamic Global Illumination (GI). On top of GI, Lumen is also capable of reflections, which are a hybrid of raytracing and screen-space reflections.</p>\n\n<p>Other things about Lumen you might want to know:</p>\n\n<ul><li>Supports only movable lights</li><li>Supports only basic transparency/translucency</li><li>Supports Virtual Heightmap</li><li>Not fully compatible with non-Nanite meshes</li><li>Only produces screen-space bounces on landscape</li><li>Compatible with volumetric fog</li></ul>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/dae25ccd5770ba38189f.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/dae25ccd5770ba38189f.webp\" width=\"1150\" height=\"581\" style=\"--source-width:566px\" alt=\"Illustration 15\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p>Continuing the Lumen discussion, the artist went on to share some of his test results:</p>\n\n<ul><li>Lumen GI supports all types of light (point, directional, emissive, spot &amp; rect)</li></ul>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/754801c2083e8e5c359f.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/754801c2083e8e5c359f.webp\" width=\"1014\" height=\"325\" style=\"--source-width:566px\" alt=\"Illustration 16\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<ul><li>These types of light can interact with volumetric fog</li><li>Strong volumetric fog can also affect GI</li><li>Lumen reflections seem less accurate than Screen Space reflections</li><li>Pretty good performance on PC &amp; PS5</li><li>Shadow calculations become a problem (due to fast light rendering)</li><li>And it is very simple to set up</li></ul>\n\n<p>Lumen setup</p>\n\n<p><strong>Step 1</strong>: enable Lumen in project setting</p>\n\n<ul><li>Global illumination: Lumen</li><li>Reflection: Lumen</li></ul>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/452b285c6e78917b5c4a.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/452b285c6e78917b5c4a.webp\" width=\"650\" height=\"716\" style=\"--source-width:363px\" alt=\"Illustration 17\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><strong>Step 2</strong>: enable lumen in PostProcessVolume</p>\n\n<ul><li>Global illumination: Lumen</li><li>Reflection: Lumen</li></ul>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/770d402ab7d488500234.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/770d402ab7d488500234.webp\" width=\"649\" height=\"577\" style=\"--source-width:450px\" alt=\"Illustration 18\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p>When testing Lumen, the artist encountered a situation in which the Screen Space GI flicks on and off when light moves in and out of the frame. Here is the video of the situation.Your browser does not support the HTML5 video element</p>\n\n<p>There are two ways:</p>\n\n<ul><li>Disable \"Affect Distance Field Lighting\" in the dome mesh details</li><li>Tick an option on the HDRI material called \"Is sky\"</li></ul>\n\n<p>Thank you Louis!</p>\n\n<h4>Nanite</h4>\n\n<p>Nanite</p>\n\n<p>Nanite is a new system that allows real-time rendering of massive amounts of geometric detail. It can automatically author LODs.</p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/6e25b6c337cedd1e14f4.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/6e25b6c337cedd1e14f4.webp\" width=\"1150\" height=\"313\" style=\"--source-width:566px\" alt=\"Illustration 19\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p>Other noteworthy findings include:</p>\n\n<ul><li>Has a Voxel-based hierarchical structure</li><li>Provides adjustable proxy geometry for collisions and navigation</li><li>Comes packaged with Virtual texture</li><li>Supports virtual texture painting on 3D models</li></ul>\n\n<p>As for disk space, Nanite:</p>\n\n<ul><li>Reduces the collective size of all textures (normal map, displacement map)</li><li>A Nanite mesh is nearly 8 times smaller than a hi-poly static mesh with 4 LODs</li></ul>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/9947e4429a1157587619.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/9947e4429a1157587619.webp\" width=\"1150\" height=\"534\" style=\"--source-width:566px\" alt=\"Illustration 20\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/3d5baa86c266257a0190.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/3d5baa86c266257a0190.webp\" width=\"1150\" height=\"534\" style=\"--source-width:566px\" alt=\"Illustration 21\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<p>Nanite Mesh with 4k Detail Normal Map vs. High Poly Static Mesh with 4k Normal Map</p>\n\n<h4>Virtual shadow maps</h4>\n\n<p>Virtual Shadow Maps</p>\n\n<p>This system combines all static and dynamic shadow maps. It updates shadow information based on changes, instead of a frame-to-frame basis.</p>\n\n<p>Some other noteworthy details are:</p>\n\n<ul><li>Supports penumbra shadow (sharpness changes according to distance)</li><li>Supports light radius</li><li>Designed for Nanite</li></ul>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/9efd450f9fe4ae7c547d.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/9efd450f9fe4ae7c547d.webp\" width=\"723\" height=\"281\" style=\"--source-width:566px\" alt=\"Illustration 22\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<h4>World partition</h4>\n\n<p>World partition</p>\n\n<p>This system replaces World Composition as the solution for distance-based streaming. It turns the game world into a grid comprised of small, stream-able cells.</p>\n\n<p>Some other details include:</p>\n\n<ul><li>Supports 3D grid and nested World Partition through Level Instance</li><li>Provides automatic HLOD for cells &amp; automatic HLOD of HLODs (combining multiple cells into one HLOD)</li><li>Supports Data Layers for cells</li></ul>\n\n<p><a class=\"source-figure\" href=\"assets/library-inline/cb4e005ab2a5b5867da8.webp\" target=\"_blank\" rel=\"noopener noreferrer\"><img src=\"assets/library-inline/cb4e005ab2a5b5867da8.webp\" width=\"1150\" height=\"649\" style=\"--source-width:566px\" alt=\"Illustration 23\" loading=\"lazy\" decoding=\"async\"></a></p>\n\n<h3><span class=\"source-divider\" role=\"separator\"></span>Recording</h3>\n\n<p>Thank you for reading and happy creating!</p>";
export const images = ["assets/library-inline/0077a445037946b2c768.webp", "assets/library-inline/10b0284cb6c2f62a4fb3.webp", "assets/library-inline/151e1041c2c5a2a6bdad.webp", "assets/library-inline/3d5baa86c266257a0190.webp", "assets/library-inline/413ea56cf67b466ea74c.webp", "assets/library-inline/452b285c6e78917b5c4a.webp", "assets/library-inline/588fd1faca4137052bcd.webp", "assets/library-inline/6e25b6c337cedd1e14f4.webp", "assets/library-inline/754801c2083e8e5c359f.webp", "assets/library-inline/76608a74949b904a969a.webp", "assets/library-inline/770d402ab7d488500234.webp", "assets/library-inline/79dc352c7c752c693e6e.webp", "assets/library-inline/7a164c3072ae991f1bbf.webp", "assets/library-inline/97c4954b6900f9ee08bf.webp", "assets/library-inline/9947e4429a1157587619.webp", "assets/library-inline/9efd450f9fe4ae7c547d.webp", "assets/library-inline/a85b47574aae3fc17b72.webp", "assets/library-inline/cb4e005ab2a5b5867da8.webp", "assets/library-inline/dae25ccd5770ba38189f.webp", "assets/library-inline/e0b406c8db5443723576.webp"];
